1	import { type ICtx, Scene, type SceneFrame } from "@threenative/core";
2	import { CollisionShape3D, type IPhysicsContext, RigidBody3D } from "@threenative/physics";
3	import { type Mesh, type PerspectiveCamera, Vector3 } from "three";
4	import { applyDirectDamage, applyRadiusDamage } from "../combat/damage.js";
5	import { Pickup } from "../entities/Pickup.js";
6	import {
7	  FRIENDLY_LAYER,
8	  HOSTILE_LAYER,
9	  PLAYER_LAYER,
10	  Player,
11	  SPAWN,
12	  WORLD_LAYER,
13	} from "../entities/Player.js";
14	import { Target } from "../entities/Target.js";
15	import { SpawnPoints } from "../level/SpawnPoints.js";
16	import { emitPlaytestEvent } from "../playtest-events.js";
17	import { createArenaCamera } from "../render/camera.js";
18	import { setupLighting } from "../render/lighting.js";
19	import { createLoadingScreen } from "../render/loading.js";
20	import { createMaterials } from "../render/materials.js";
21	import { setupPost } from "../render/postprocessing.js";
22	import { createArena, createFriendlyVisual, createWallVisual } from "../render/shapes.js";
23	import { setupSky } from "../render/sky.js";
24	import type { GameState } from "../state.js";
25	import { WaveDirector } from "../waves.js";
26	import { Hitscan } from "../weapons/Hitscan.js";
27	import { Projectile } from "../weapons/Projectile.js";
28	
29	export type GameCtx = ICtx<GameState, IPhysicsContext>;
30	
31	const AIM = new Vector3(0, 0, -1);
32	const DEMO_POSITION = new Vector3(0, 0.85, -4);
33	const WAVE_POSITION = new Vector3(0, 0.9, -9);
34	const SCAN_POSITION = new Vector3(3, 0.9, 0);
35	const BLAST_CENTRE = new Vector3(0, 0.85, -4);
36	const SPAWN_POINTS = new SpawnPoints([
37	  new Vector3(-0.4, SPAWN.y, SPAWN.z),
38	  SPAWN,
39	  new Vector3(0.4, SPAWN.y, SPAWN.z),
40	]);
41	
42	type TargetEntry = { readonly id: string; readonly target: Target };
43	
44	export class Play extends Scene<GameState, IPhysicsContext> {
45	  static override readonly initialState: GameState = {
46	    armor: 0,
47	    deaths: 0,
48	    demoTargetAlive: 1,
49	    friendlyPassed: 0,
50	    gameOver: 0,
51	    gameWon: 0,
52	    health: 100,
53	    hitDistanceTenths: 0,
54	    hitNormalXPercent: -101,
55	    hitNormalYPercent: -101,
56	    hitNormalZPercent: -101,
57	    lives: 3,
58	    pickups: 0,
59	    radiusInsideDeaths: 0,
60	    radiusMidAlive: 1,
61	    radiusNearAlive: 1,
62	    radiusOutsideAlive: -1,
63	    respawns: 0,
64	    scanCount: 0,
65	    score: 0,
66	    targetsRemaining: 1,
67	    wave: 1,
68	    wavesCleared: 0,
69	    wallBlocked: 0,
70	    phase: "playing",
71	  };
72	
73	  override enter(ctx: GameCtx): SceneFrame<GameState, IPhysicsContext> {
74	    const camera = ctx.camera as PerspectiveCamera;
75	    const materials = createMaterials();
76	    setupSky(ctx.scene);
77	    setupLighting(ctx.scene, ctx.renderer.raw as Parameters<typeof setupLighting>[1]);
78	    setupPost(ctx.renderer, ctx.scene, camera);
79	    const loading = createLoadingScreen(ctx);
80	    ctx.add(camera);
81	    const rig = createArenaCamera(camera);
82	    ctx.viewport.resize();
83	
84	    const arena = createArena(materials);
85	    ctx.add(arena.group);
86	    const arenaBody = (object: Mesh, shape: CollisionShape3D): RigidBody3D =>
87	      new RigidBody3D({
88	        collisionLayer: WORLD_LAYER,
89	        collisionMask: PLAYER_LAYER | HOSTILE_LAYER | FRIENDLY_LAYER,
90	        object,
91	        physics: ctx.physics,
92	        shape,
93	        type: "fixed",
94	      });
95	    arenaBody(arena.floor, CollisionShape3D.box(22, 0.4, 20));
96	    for (const wall of arena.walls) arenaBody(wall, CollisionShape3D.fromMesh(wall));
97	
98	    const playerRef: { value?: Player } = {};
99	    const getPlayer = (): Player => {
100	      if (playerRef.value === undefined) throw new Error("Shooter player is not initialized.");
101	      return playerRef.value;
102	    };
103	    const targets = new Map<number, Target>();
104	    const waveTargets: TargetEntry[] = [];
105	    const projectiles: Array<{ readonly id: string; readonly value: Projectile }> = [];
106	    let projectileIndex = 0;
107	    const waveDirector = new WaveDirector();
108	    const hitscan = new Hitscan();
109	    const spawnPoints = SPAWN_POINTS;
110	    const elapsed = { value: 0 };
111	
112	    const createEnemyProjectile = (origin: Vector3): void => {
113	      const direction = getPlayer().mesh.position.clone().sub(origin).normalize();
114	      const id = `projectile.enemy.${projectileIndex++}`;
115	      const projectile = new Projectile(
116	        ctx,
117	        materials,
118	        origin,
119	        direction,
120	        WORLD_LAYER | PLAYER_LAYER,
121	        (hit) => {
122	          if (hit.body.id === getPlayer().body.body.id) {
123	            getPlayer().takeDamage(20);
124	            emitPlaytestEvent({ entity: "player", name: "projectile-hit" });
125	          }
126	        },
127	      );
128	      projectiles.push({ id, value: projectile });
129	      ctx.entities.add(id, projectile);
130	    };
131	
132	    const registerTarget = (
133	      id: string,
134	      position: Vector3,
135	      options: ConstructorParameters<typeof Target>[3] = {},
136	      scan = true,
137	    ): Target => {
138	      const target = new Target(ctx, materials, position, {
139	        ...options,
140	        onFire: options.onFire ?? createEnemyProjectile,
141	      });
142	      targets.set(target.body.body.id, target);
143	      ctx.entities.add(id, target);
144	      if (scan) target.startScanning(ctx, getPlayer().body.body.id);
145	      return target;
146	    };
147	
148	    const removeEntity = (id: string): void => {
149	      if (ctx.entities.get(id) !== undefined) ctx.entities.remove(id);
150	    };
151	
152	    const onDamage = (amount: number): void => {
153	      const previous = ctx.state.getState();
154	      ctx.state.set({ health: getPlayer().health, score: previous.score, armor: 0 });
155	      emitPlaytestEvent({ entity: "player", name: "damaged", amount });
156	    };
157	
158	    const onDeath = (): void => {
159	      const previous = ctx.state.getState();
160	      const lives = Math.max(0, previous.lives - 1);
161	      const deaths = previous.deaths + 1;
162	      ctx.state.set({
163	        deaths,
164	        gameOver: lives === 0 ? 1 : 0,
165	        lives,
166	        phase: lives === 0 ? "lost" : "dead",
167	      });
168	      emitPlaytestEvent({ entity: "player", name: "died", lives });
169	      if (lives === 0) return;
170	      ctx.after(0.5, () => {
171	        waveDirector.reset();
172	        const spawn = spawnPoints.furthestFrom(waveTargets.map(({ target }) => target));
173	        getPlayer().respawn(spawn);
174	        const state = ctx.state.getState();
175	        ctx.state.set({
176	          health: getPlayer().health,
177	          phase: "playing",
178	          respawns: state.respawns + 1,
179	          wave: waveDirector.wave,
180	          wavesCleared: waveDirector.cleared,
181	        });
182	        emitPlaytestEvent({ entity: "player", name: "respawned" });
183	      });
184	    };
185	
186	    const player = new Player(ctx, materials, SPAWN.clone(), onDamage, onDeath);
187	    playerRef.value = player;
188	    ctx.entities.add("player", player);
189	
190	    const demo = registerTarget(
191	      "demo-target",
192	      DEMO_POSITION,
193	      { health: 20, onFire: () => undefined },
194	      false,
195	    );
196	    registerTarget("scan-target", SCAN_POSITION, { health: 20, onFire: () => undefined });
197	    const friendly = createFriendlyVisual(materials);
198	    friendly.name = "friendly-drone";
199	    friendly.position.set(0, 1, 2.2);
200	    ctx.add(friendly);
201	    const friendlyBody = new RigidBody3D({
202	      collisionLayer: FRIENDLY_LAYER,
203	      collisionMask: 0,
204	      object: friendly,
205	      physics: ctx.physics,
206	      shape: CollisionShape3D.box(0.9, 1.4, 0.9),
207	      type: "fixed",
208	    });
209	
210	    const wall = createWallVisual(materials);
211	    wall.name = "probe-wall";
212	    wall.position.set(4, 1.4, 5);
213	    ctx.add(wall);
214	    const wallBody = new RigidBody3D({
215	      collisionLayer: WORLD_LAYER,
216	      collisionMask: PLAYER_LAYER | FRIENDLY_LAYER,
217	      object: wall,
218	      physics: ctx.physics,
219	      shape: CollisionShape3D.box(0.65, 2.8, 2.8),
220	      type: "fixed",
221	    });
222	
223	    const radiusNear = registerTarget(
224	      "radius.near",
225	      new Vector3(0.8, 0.85, -4),
226	      { health: 30, onFire: () => undefined },
227	      false,
228	    );
229	    const radiusMid = registerTarget(
230	      "radius.mid",
231	      new Vector3(-1.8, 0.85, -4),
232	      { health: 30, onFire: () => undefined },
233	      false,
234	    );
235	    const radiusOutside = registerTarget(
236	      "radius.outside",
237	      new Vector3(6.5, 0.85, -4),
238	      { health: 30, onFire: () => undefined },
239	      false,
240	    );
241	
242	    const pickup = new Pickup(
243	      ctx,
244	      materials,
245	      new Vector3(-1.2, SPAWN.y, SPAWN.z),
246	      player.body.body.id,
247	      () => {
248	        player.health = Math.min(player.maxHealth, player.health + 60);
249	        const state = ctx.state.getState();
250	        ctx.state.set({
251	          armor: state.armor + 1,
252	          health: player.health,
253	          pickups: state.pickups + 1,
254	        });
255	        emitPlaytestEvent({ entity: "player", name: "collected" });
256	        ctx.after(4, () => pickup.respawn());
257	      },
258	    );
259	    ctx.entities.add("health-pickup", pickup);
260	
261	    const spawnWave = (wave: number): void => {
262	      const target = registerTarget(`wave.target.${wave}`, WAVE_POSITION.clone(), {
263	        health: 35,
264	        wave,
265	      });
266	      waveTargets.push({ id: `wave.target.${wave}`, target });
267	      ctx.state.set({ targetsRemaining: 1, wave });
268	      emitPlaytestEvent({ entity: "wave", name: "started", wave });
269	    };
270	    waveDirector.start(spawnWave);
271	    rig.snap(player.mesh.position);
272	
273	    const fireHitscan = (): void => {
274	      const hit = hitscan.fire(ctx.physics, player.aimOrigin(), AIM, HOSTILE_LAYER);
275	      if (hit === undefined) return;
276	      const state = ctx.state.getState();
277	      const target = targets.get(hit.body.id);
278	      if (target !== undefined) applyDirectDamage(targets, hit.body.id, 40);
279	      const demoHit = hit.body.id === demo.body.body.id;
280	      ctx.state.set({
281	        demoTargetAlive: demo.alive ? 1 : 0,
282	        friendlyPassed: demoHit && friendlyBody.body.id !== hit.body.id ? 1 : state.friendlyPassed,
283	        ...(demoHit
284	          ? {
285	              hitDistanceTenths: Math.round(hit.distance * 10),
286	              hitNormalXPercent: Math.round(hit.normal.x * 100),
287	              hitNormalYPercent: Math.round(hit.normal.y * 100),
288	              hitNormalZPercent: Math.round(hit.normal.z * 100),
289	            }
290	          : {}),
291	      });
292	      emitPlaytestEvent({
293	        entity: "player",
294	        name: "hit",
295	        distanceTenths: Math.round(hit.distance * 10),
296	      });
297	      if (target?.alive === false) emitPlaytestEvent({ entity: "target", name: "defeated" });
298	    };
299	
300	    const fireProjectile = (): void => {
301	      const id = `projectile.player.${projectileIndex++}`;
302	      const projectile = new Projectile(
303	        ctx,
304	        materials,
305	        player.aimOrigin(),
306	        AIM,
307	        HOSTILE_LAYER | WORLD_LAYER,
308	        (hit) => {
309	          if (applyDirectDamage(targets, hit.body.id, 22))
310	            emitPlaytestEvent({ entity: "player", name: "projectile-defeated" });
311	        },
312	      );
313	      projectiles.push({ id, value: projectile });
314	      ctx.entities.add(id, projectile);
315	    };
316	
317	    const fireRadius = (): void => {
318	      applyRadiusDamage(ctx.physics, BLAST_CENTRE, 3.5, 80, targets);
319	      const insideDeaths = [radiusNear, radiusMid].filter(
320	        (target) => target.alive === false,
321	      ).length;
322	      ctx.state.set({
323	        radiusInsideDeaths: insideDeaths,
324	        radiusMidAlive: radiusMid.alive ? 1 : 0,
325	        radiusNearAlive: radiusNear.alive ? 1 : 0,
326	        radiusOutsideAlive: radiusOutside.alive ? 1 : 0,
327	      });
328	      emitPlaytestEvent({ entity: "player", name: "radius-damage", defeated: insideDeaths });
329	    };
330	
331	    const probeWall = (): void => {
332	      const from = player.mesh.position.clone().add(new Vector3(0, 0.75, 0));
333	      const to = from.clone().add(new Vector3(10, 0, 0));
334	      const hit = hitscan.probe(ctx.physics, from, to, WORLD_LAYER | FRIENDLY_LAYER);
335	      if (hit?.body.id !== wallBody.body.id) return;
336	      ctx.state.set({ wallBlocked: 1 });
337	      emitPlaytestEvent({ entity: "player", name: "wall-blocked" });
338	    };
339	
340	    const removeDeadTargets = (): void => {
341	      if (!demo.alive && ctx.entities.get("demo-target") !== undefined) {
342	        removeEntity("demo-target");
343	        targets.delete(demo.body.body.id);
344	      }
345	      for (let index = waveTargets.length - 1; index >= 0; index -= 1) {
346	        const entry = waveTargets[index];
347	        if (entry?.target.alive !== false) continue;
348	        removeEntity(entry.id);
349	        targets.delete(entry.target.body.body.id);
350	        waveTargets.splice(index, 1);
351	      }
352	    };
353	
354	    const restart = (frameCtx: GameCtx): boolean => {
355	      if (!frameCtx.input.justPressed("restart")) return false;
356	      frameCtx.state.set(Play.initialState);
357	      frameCtx.state.flush();
358	      void frameCtx.goto("play");
359	      return true;
360	    };
361	
362	    const handleInput = (frameCtx: GameCtx): void => {
363	      if (frameCtx.input.justPressed("fire")) fireHitscan();
364	      if (frameCtx.input.justPressed("projectile")) fireProjectile();
365	      if (frameCtx.input.justPressed("blast")) fireRadius();
366	      if (frameCtx.input.justPressed("probe")) probeWall();
367	      if (frameCtx.input.justPressed("damage")) player.takeDamage(35);
368	      if (frameCtx.input.justPressed("lethal")) player.takeDamage(player.health + 1);
369	    };
370	
371	    const updateProjectiles = (frameCtx: GameCtx, dt: number): void => {
372	      for (const entry of [...projectiles]) {
373	        entry.value.update(frameCtx, dt);
374	        if (!entry.value.dead) continue;
375	        removeEntity(entry.id);
376	        projectiles.splice(projectiles.indexOf(entry), 1);
377	      }
378	    };
379	
380	    const updateWaves = (frameCtx: GameCtx): void => {
381	      waveDirector.update(
382	        frameCtx,
383	        waveTargets.filter(({ target }) => target.alive).length,
384	        spawnWave,
385	        (wave) => {
386	          const state = frameCtx.state.getState();
387	          frameCtx.state.set({ score: state.score + 100, wavesCleared: waveDirector.cleared });
388	          emitPlaytestEvent({ entity: "wave", name: "cleared", wave });
389	        },
390	      );
391	      if (waveDirector.won) frameCtx.state.set({ gameWon: 1, phase: "won" });
392	    };
393	
394	    const syncStateAndHud = (frameCtx: GameCtx): void => {
395	      const liveTargets = waveTargets.filter(({ target }) => target.alive).length;
396	      const currentScanCount = [...targets.values()].reduce(
397	        (sum, target) => sum + target.scanCount,
398	        0,
399	      );
400	      const previous = frameCtx.state.getState();
401	      const scanCount = Math.max(previous.scanCount, currentScanCount);
402	      frameCtx.state.set({
403	        health: player.health,
404	        scanCount,
405	        targetsRemaining: liveTargets,
406	        wave: waveDirector.wave,
407	        wavesCleared: waveDirector.cleared,
408	      });
409	    };
410	
411	    return (frameCtx, dt) => {
412	      loading.update();
413	      elapsed.value += dt;
414	      if (restart(frameCtx)) return;
415	      handleInput(frameCtx);
416	
417	      player.update(frameCtx, dt);
418	      hitscan.update(dt);
419	      updateProjectiles(frameCtx, dt);
420	      for (const target of targets.values()) target.update(dt);
421	      pickup.update(dt);
422	      removeDeadTargets();
423	      updateWaves(frameCtx);
424	      syncStateAndHud(frameCtx);
425	      rig.follow(player.mesh.position, dt);
426	    };
427	  }
428	}
