1	import type { ICtx, ScheduleHandle } from "@threenative/core";
2	import { CollisionShape3D, type IPhysicsContext, RigidBody3D } from "@threenative/physics";
3	import { type Group, Vector3 } from "three";
4	import { directSpaceState } from "../physics.js";
5	import { createTargetVisual } from "../render/shapes.js";
6	import type { GameState } from "../state.js";
7	import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";
8	
9	type GameCtx = ICtx<GameState, IPhysicsContext>;
10	
11	const SCAN_RADIUS = 7;
12	
13	export class Target {
14	  readonly mesh: Group;
15	  readonly body: RigidBody3D;
16	  readonly tags = ["hostile", "target"];
17	  readonly wave: number | undefined;
18	  health: number;
19	  alive = true;
20	  acquired = false;
21	  scanCount = 0;
22	  #scanHandle: ScheduleHandle | undefined;
23	  #fireTimer = 0;
24	  #onFire: (origin: Vector3) => void;
25	  #scanShape = CollisionShape3D.sphere(SCAN_RADIUS);
26	
27	  constructor(
28	    ctx: GameCtx,
29	    materials: Parameters<typeof createTargetVisual>[0],
30	    position: Vector3,
31	    options: {
32	      readonly health?: number;
33	      readonly onFire?: (origin: Vector3) => void;
34	      readonly wave?: number;
35	    } = {},
36	  ) {
37	    this.wave = options.wave;
38	    this.health = options.health ?? 40;
39	    this.#onFire = options.onFire ?? (() => undefined);
40	    this.mesh = createTargetVisual(materials);
41	    this.mesh.position.copy(position);
42	    ctx.add(this.mesh);
43	    this.body = new RigidBody3D({
44	      collisionLayer: HOSTILE_LAYER,
45	      collisionMask: WORLD_LAYER,
46	      object: this.mesh,
47	      physics: ctx.physics,
48	      shape: CollisionShape3D.box(1.2, 1.8, 1),
49	      type: "kinematic",
50	    });
51	  }
52	
53	  startScanning(ctx: GameCtx, playerBodyId: number): void {
54	    const scan = (): void => {
55	      if (!this.alive) return;
56	      this.scanCount += 1;
57	      const hits = directSpaceState(ctx.physics).intersectShape({
58	        collisionMask: PLAYER_LAYER,
59	        maxResults: 4,
60	        position: this.mesh.position,
61	        shape: this.#scanShape,
62	      });
63	      this.acquired = hits.some((hit) => hit.body.id === playerBodyId);
64	      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
65	    };
66	    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
67	  }
68	
69	  update(dt: number): void {
70	    if (!this.alive || !this.acquired) return;
71	    this.#fireTimer -= dt;
72	    if (this.#fireTimer > 0) return;
73	    this.#fireTimer = 6;
74	    this.#onFire(this.mesh.position.clone().add(new Vector3(0, 0.9, 0)));
75	  }
76	
77	  takeDamage(amount: number): boolean {
78	    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
79	    this.health = Math.max(0, this.health - amount);
80	    if (this.health > 0) return false;
81	    this.alive = false;
82	    this.mesh.visible = false;
83	    return true;
84	  }
85	
86	  debug(): Record<string, unknown> {
87	    return {
88	      acquired: this.acquired,
89	      alive: this.alive,
90	      health: this.health,
91	      position: this.mesh.position.toArray(),
92	      scanCount: this.scanCount,
93	      selected: this.acquired ? 1 : 0,
94	      wave: this.wave ?? 0,
95	    };
