export type ShooterMaterials = ReturnTypeOfMaterials;

function compactBox(width: number, height: number, depth: number): BufferGeometry {
  const halfX = width / 2;
  const halfY = height / 2;
  const halfZ = depth / 2;
  const positions = new Float32Array([
    -halfX,
