import type { ICtx, ScheduleHandle } from "@threenative/core";
import { attachToBone } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { NavigationAgent3D, type NavigationRegion3D } from "@threenative/physics/navigation";
import { type Group, Mesh, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createEnemyVisual, createRifleVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const SCAN_RADIUS = 8;
const PATROL_SPEED = 2.5;
const CHASE_SPEED = 3.5;
const SHOOT_RANGE = 15;
const SHOOT_INTERVAL = 1.2;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  health: number;
  alive = true;
  acquired = false;
  #scanShape = CollisionShape3D.sphere(SCAN_RADIUS);
  #scanHandle: ScheduleHandle | undefined;
  #fireTimer = 0;
  #navAgent: NavigationAgent3D;
  #patrolPoints: Vector3[];
  #currentPatrolIndex = 0;
  #onFire: (origin: Vector3) => void;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    navigation: NavigationRegion3D,
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3) => void;
      readonly patrolPoints?: Vector3[];
    } = {},
  ) {
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#patrolPoints = options.patrolPoints ?? [
      new Vector3(3, 0, 0),
      new Vector3(3, 0, -6),
      new Vector3(-3, 0, -6),
      new Vector3(-3, 0, 0),
    ];

    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.35),
    });

    this.#navAgent = new NavigationAgent3D({
      navigation,
      object: this.mesh,
    });

    const rifle = createRifleVisual(materials);
    attachToBone(this.mesh, "RightHand", rifle);
  }

  startScanning(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const hits = directSpaceState(ctx.physics).intersectShape({
        collisionMask: PLAYER_LAYER,
        maxResults: 4,
        position: this.mesh.position,
        shape: this.#scanShape,
      });
      this.acquired = hits.some((hit) => hit.body.id === playerBodyId);
      this.#scanHandle = ctx.after(ctx.random.range(6, 12) / 60, scan);
    };
    this.#scanHandle = ctx.after(ctx.random.range(6, 12) / 60, scan);
  }

  update(ctx: GameCtx, playerPosition: Vector3, dt: number): void {
    if (!this.alive) return;

    if (this.acquired) {
      const toPlayer = playerPosition.clone().sub(this.mesh.position);
      const distance = toPlayer.length();

      if (distance < SHOOT_RANGE) {
        this.#fireTimer -= dt;
        if (this.#fireTimer <= 0) {
          this.#onFire(this.mesh.position.clone().add(new Vector3(0.2, 0.9, 0)));
          this.#fireTimer = SHOOT_INTERVAL;
        }
      }

      this.#navAgent.setTargetPosition(playerPosition);
      const nextPos = this.#navAgent.getNextPathPosition();
      if (nextPos) {
        const direction = nextPos.clone().sub(this.mesh.position);
        this.body.velocity.x = direction.x * CHASE_SPEED;
        this.body.velocity.z = direction.z * CHASE_SPEED;
      }
    } else {
      const targetPoint = this.#patrolPoints[this.#currentPatrolIndex];
      const toTarget = targetPoint.clone().sub(this.mesh.position);
      const distanceToTarget = toTarget.length();

      if (distanceToTarget < 1.5) {
        this.#currentPatrolIndex = (this.#currentPatrolIndex + 1) % this.#patrolPoints.length;
      }

      this.#navAgent.setTargetPosition(targetPoint);
      const nextPos = this.#navAgent.getNextPathPosition();
      if (nextPos) {
        const direction = nextPos.clone().sub(this.mesh.position);
        this.body.velocity.x = direction.x * PATROL_SPEED;
        this.body.velocity.z = direction.z * PATROL_SPEED;
      }
    }

    this.body.moveAndSlide(dt);
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      acquired: this.acquired,
      alive: this.alive,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

