    armor: 0,
    deaths: 0,
    demoTargetAlive: 1,
    friendlyPassed: 0,
    gameOver: 0,
    gameWon: 0,
    health: 100,
    hitDistanceTenths: 0,
    hitNormalXPercent: -101,
    hitNormalYPercent: -101,
    hitNormalZPercent: -101,
    lives: 3,
    pickups: 0,
    radiusInsideDeaths: 0,
    radiusMidAlive: 1,
    radiusNearAlive: 1,
    radiusOutsideAlive: -1,
    respawns: 0,
    scanCount: 0,
    score: 0,
    targetsRemaining: 1,
    wave: 1,
    wavesCleared: 0,
